                                         FT_SERVICE_ID_MULTI_MASTERS,
                                         0 );
     }

     FT_FACE_FIND_GLOBAL_SERVICE( face, face->var, METRICS_VARIATIONS );
 #endif

     FT_TRACE2(( "SFNT driver\n" ));

     error = sfnt_open_font( stream, face );
     if ( error )
       return error;

     /* Stream may have changed in sfnt_open_font. */
     stream = face->root.stream;

     FT_TRACE2(( "sfnt_init_face: %08p, %ld\n", face, face_instance_index ));

     face_index = FT_ABS( face_instance_index ) & 0xFFFF;

     if ( face_index >= face->ttc_header.count )
     {
       if ( face_instance_index >= 0 )
         return FT_THROW( Invalid_Argument );
       else
         face_index = 0;
     }

     if ( FT_STREAM_SEEK( face->ttc_header.offsets[face_index] ) )
       return error;

     /* check whether we have a valid TrueType file */
     error = sfnt->load_font_dir( face, stream );
     if ( error )
       return error;

     face->is_default_instance = 1;

 #ifdef TT_CONFIG_OPTION_GX_VAR_SUPPORT
     {
       FT_ULong  fvar_len;

       FT_ULong  version;
       FT_ULong  offset;

       FT_UShort  num_axes;
       FT_UShort  axis_size;
       FT_UShort  num_instances;
       FT_UShort  instance_size;

       FT_Int  instance_index;


       instance_index = FT_ABS( face_instance_index ) >> 16;

       /* test whether current face is a GX font with named instances */
       if ( face->goto_table( face, TTAG_fvar, stream, &fvar_len ) ||
            fvar_len < 20                                          ||
            FT_READ_ULONG( version )                               ||
            FT_READ_USHORT( offset )                               ||
            FT_STREAM_SKIP( 2 )                                    ||
            FT_READ_USHORT( num_axes )                             ||
            FT_READ_USHORT( axis_size )                            ||
            FT_READ_USHORT( num_instances )                        ||
            FT_READ_USHORT( instance_size )                        )
       {
         version       = 0;
         offset        = 0;
         num_axes      = 0;
         axis_size     = 0;
         num_instances = 0;
         instance_size = 0;
       }

       /* check that the data is bound by the table length; */
       /* based on similar code in function `TT_Get_MM_Var' */
       if ( version != 0x00010000UL                    ||
            axis_size != 20                            ||
+           num_axes == 0                              ||
            num_axes > 0x3FFE                          ||
            instance_size != 4 + 4 * num_axes          ||
            num_instances > 0x7EFF                     ||
            offset                          +
              axis_size * num_axes          +
              instance_size * num_instances > fvar_len )
         num_instances = 0;

       /* we don't support Multiple Master CFFs yet */
       if ( !face->goto_table( face, TTAG_CFF, stream, 0 ) )
         num_instances = 0;

       /* we support at most 2^15 - 1 instances */
       if ( num_instances >= ( 1U << 15 ) - 1 )
       {
         if ( face_instance_index >= 0 )
           return FT_THROW( Invalid_Argument );
         else
           num_instances = 0;
       }

       /* instance indices in `face_instance_index' start with index 1, */
       /* thus `>' and not `>='                                         */
       if ( instance_index > num_instances )
       {
         if ( face_instance_index >= 0 )
           return FT_THROW( Invalid_Argument );
         else
           num_instances = 0;
       }

       face->root.style_flags = (FT_Long)num_instances << 16;
     }
 #endif

     face->root.num_faces  = face->ttc_header.count;
     face->root.face_index = face_instance_index;

     return error;
   }


